from django.utils.encoding import force_text

class ConverterToPython:
    """
    A utility class for converting string representations to Python objects.
    This class centralizes string-to-Python conversion logic used by database backends.
    """

    @classmethod
    def to_bool(cls, value):
        """Convert a string to a boolean value."""
        if isinstance(value, bool):
            return value
        if value in ('1', 't', 'T', 'true', 'True', 'TRUE'):
            return True
        if value in ('0', 'f', 'F', 'false', 'False', 'FALSE'):
            return False
        raise ValueError("Invalid boolean value: %s" % value)

    @classmethod
    def to_int(cls, value):
        """Convert a string to an integer."""
        if isinstance(value, six.integer_types):
            return value
        try:
            return int(value)
        except (ValueError, TypeError):
            raise ValueError("Invalid integer value: %s" % value)

    @classmethod
    def to_float(cls, value):
        """Convert a string to a float."""
        if isinstance(value, float):
            return value
        try:
            return float(value)
        except (ValueError, TypeError):
            raise ValueError("Invalid float value: %s" % value)

    @classmethod
    def to_str(cls, value):
        """Convert a value to a string."""
        if isinstance(value, six.string_types):
            return value
        return force_text(value)

    @classmethod
    def to_bytes(cls, value):
        """Convert a value to bytes."""
        if isinstance(value, bytes):
            return value
        if isinstance(value, six.string_types):
            return value.encode('utf-8')
        return str(value).encode('utf-8')

