from django.utils.deprecation import RemovedInDjango50Warning

class Timezone:
    """
    A utility class for handling timezone-related operations in Django forms.
    """

    @classmethod
    def get_current_timezone(cls):
        """
        Returns the current timezone, either from settings or default UTC.
        """
        return getattr(settings, 'TIME_ZONE', 'UTC')

    @classmethod
    def get_timezone(cls, timezone):
        """
        Returns a timezone object from a timezone string or None.
        """
        if timezone is None:
            return None
        return pytz.timezone(timezone)

    @classmethod
    def localize(cls, value, timezone=None):
        """
        Localizes a naive datetime to the specified timezone.
        """
        if timezone is None:
            timezone = cls.get_current_timezone()

        tz = cls.get_timezone(timezone)
        if tz is None:
            return value

        if value is None:
            return None

        if isinstance(value, datetime.datetime):
            if value.tzinfo is None:
                return tz.localize(value)
            return value.astimezone(tz)
        return value

    @classmethod
    def normalize_timezone(cls, value):
        """
        Normalizes timezone input to a consistent format.
        """
        if value is None:
            return None
        if isinstance(value, str):
            return value.strip().upper()
        return str(value)

    @classmethod
    def is_aware(cls, value):
        """
        Determines if a datetime is timezone-aware.
        """
        return value is not None and hasattr(value, 'tzinfo') and value.tzinfo is not None

    @classmethod
    def is_naive(cls, value):
        """
        Determines if a datetime is timezone-naive.
        """
        return value is not None and (not hasattr(value, 'tzinfo') or value.tzinfo is None)

    @classmethod
    def make_aware(cls, value, timezone=None):
        """
        Makes a naive datetime aware using the specified timezone.
        """
        if timezone is None:
            timezone = cls.get_current_timezone()

        if cls.is_aware(value):
            return value

        tz = cls.get_timezone(timezone)
        if tz is None:
            raise ValueError("Invalid timezone specified")

        return tz.localize(value)

    @classmethod
    def make_naive(cls, value, timezone=None):
        """
        Makes an aware datetime naive by converting to the specified timezone.
        """
        if timezone is None:
            timezone = cls.get_current_timezone()

        if cls.is_naive(value):
            return value

        tz = cls.get_timezone(timezone)
        if tz is None:
            raise ValueError("Invalid timezone specified")

        return value.astimezone(tz).replace(tzinfo=None)
