def recursive_diff(obj1, obj2, path="", log=False):
    """
    Recursively compare two objects and return differences.

    Args:
        obj1: First object to compare
        obj2: Second object to compare
        path: Current path in the object structure (for nested objects)
        log: Whether to log differences (default: False)

    Returns:
        dict: Dictionary of differences found
    """
    differences = {}

    # Base case: if types are different
    if type(obj1) != type(obj2):
        if log:
            print(f"Type mismatch at {path}: {type(obj1)} vs {type(obj2)}")
        differences[path] = {"type1": type(obj1).__name__, "type2": type(obj2).__name__}
        return differences

    # Handle dictionaries
    if isinstance(obj1, dict):
        # Check for keys in obj1 not in obj2
        for key in obj1:
            if key not in obj2:
                if log:
                    print(f"Key missing in obj2 at {path}: {key}")
                differences[f"{path}.{key}" if path else key] = {"obj1": obj1[key], "obj2": None}
            else:
                # Recursive call with same log parameter
                nested_diff = recursive_diff(obj1[key], obj2[key], f"{path}.{key}" if path else key, log)
                if nested_diff:
                    differences.update(nested_diff)

        # Check for keys in obj2 not in obj1
        for key in obj2:
            if key not in obj1:
                if log:
                    print(f"Key missing in obj1 at {path}: {key}")
                differences[f"{path}.{key}" if path else key] = {"obj1": None, "obj2": obj2[key]}

    # Handle lists
    elif isinstance(obj1, list):
        if len(obj1) != len(obj2):
            if log:
                print(f"List length mismatch at {path}: {len(obj1)} vs {len(obj2)}")
            differences[path] = {"len1": len(obj1), "len2": len(obj2)}
        else:
            for i, (item1, item2) in enumerate(zip(obj1, obj2)):
                # Recursive call with same log parameter
                nested_diff = recursive_diff(item1, item2, f"{path}[{i}]", log)
                if nested_diff:
                    differences.update(nested_diff)

    # Handle other comparable types
    else:
        if obj1 != obj2:
            if log:
                print(f"Value mismatch at {path}: {obj1} vs {obj2}")
            differences[path] = {"obj1": obj1, "obj2": obj2}

    return differences
