### 2. Update gunzip function
```typescript
// src/utils/gunzip.ts
import { createGunzip } from 'zlib';
import { pipeline } from 'stream/promises';
import { createWriteStream } from 'fs';
import { GunzipParams } from './GunzipParams';

export async function gunzip(params: GunzipParams): Promise<Buffer | void> {
  const { input, outputPath, encoding = 'utf8', chunkSize = 16384 } = params;

  if (outputPath) {
    const gunzip = createGunzip();
    const output = createWriteStream(outputPath);
    await pipeline(input, gunzip, output);
    return;
  }

  return new Promise<Buffer>((resolve, reject) => {
    const gunzip = createGunzip();
    const chunks: Buffer[] = [];

    gunzip
      .on('data', (chunk) => chunks.push(chunk))
      .on('end', () => resolve(Buffer.concat(chunks)))
      .on('error', reject);

    for (let i = 0; i < input.length; i += chunkSize) {
      const chunk = input.subarray(i, i + chunkSize);
      gunzip.write(chunk);
    }
    gunzip.end();
  });
}
